 22	// Validator loads and applies the benchmark evidence schema from a repo root.
 23	type Validator struct {
 24		schema *jsonschema.Schema
 25	}
 26	
 27	// AppendReport summarizes the effect of an append operation.
 28	type AppendReport struct {
 29		LedgerPath string
 30		Added      int
 31		Duplicates []string
 32	}
 33	
 34	// DuplicateRecordsError reports duplicate evidence records that were skipped.
 35	type DuplicateRecordsError struct {
 36		RecordIDs []string
 37	}
 38	
 39	func (e *DuplicateRecordsError) Error() string {
 40		if e == nil || len(e.RecordIDs) == 0 {
 41			return "duplicate evidence records"
 42		}
 43		return fmt.Sprintf("duplicate evidence records: %s", strings.Join(e.RecordIDs, ", "))
 44	}
