 46	// NewValidator compiles the benchmark evidence schema from repoRoot.
 47	func NewValidator(repoRoot string) (*Validator, error) {
 48		schemaPath := filepath.Join(repoRoot, SchemaRelativePath)
 49		rawSchema, err := os.ReadFile(schemaPath)
 50		if err != nil {
 51			return nil, fmt.Errorf("read evidence schema %s: %w", schemaPath, err)
 52		}
 53	
 54		compiler := jsonschema.NewCompiler()
 55		compiler.AssertFormat = true
 56		if err := compiler.AddResource("benchmark-evidence.schema.json", bytes.NewReader(rawSchema)); err != nil {
 57			return nil, fmt.Errorf("add evidence schema: %w", err)
 58		}
 59		schema, err := compiler.Compile("benchmark-evidence.schema.json")
 60		if err != nil {
 61			return nil, fmt.Errorf("compile evidence schema: %w", err)
 62		}
 63		return &Validator{schema: schema}, nil
 64	}
