 66	// ValidateFile validates one JSON or JSONL evidence file and returns the
 67	// normalized records, including any generated record_id values.
 68	func (v *Validator) ValidateFile(path string) ([]map[string]any, error) {
 69		rawRecords, err := loadRecords(path)
 70		if err != nil {
 71			return nil, err
 72		}
 73	
 74		normalized := make([]map[string]any, 0, len(rawRecords))
 75		for i, record := range rawRecords {
 76			doc, _, err := v.normalizeRecord(record)
 77			if err != nil {
 78				return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
 79			}
 80			normalized = append(normalized, doc)
 81		}
 82		return normalized, nil
 83	}
 84	
 85	// AppendLedger appends validated evidence records to a JSONL ledger.
 86	func (v *Validator) AppendLedger(inputPath, ledgerPath string) (*AppendReport, error) {
 87		incoming, err := v.ValidateFile(inputPath)
 88		if err != nil {
 89			return nil, err
 90		}
 91	
 92		existing, err := loadLedgerRecords(ledgerPath)
 93		if err != nil {
 94			return nil, err
 95		}
 96	
 97		existingByFingerprint := make(map[string]string, len(existing))
 98		existingByID := make(map[string]string, len(existing))
 99		for _, record := range existing {
100			fp, err := fingerprintRecord(record)
101			if err != nil {
102				return nil, err
103			}
104			id, _ := record["record_id"].(string)
105			existingByFingerprint[fp] = id
106			existingByID[id] = fp
107		}
108	
109		var (
110			additions  []map[string]any
111			duplicates []string
112		)
113		seenNew := make(map[string]struct{}, len(incoming))
114		for _, record := range incoming {
115			fp, err := fingerprintRecord(record)
116			if err != nil {
117				return nil, err
118			}
119			id, _ := record["record_id"].(string)
120	
121			if existingID, ok := existingByFingerprint[fp]; ok {
122				duplicates = append(duplicates, chooseDuplicateID(id, existingID))
123				continue
124			}
125			if existingFP, ok := existingByID[id]; ok && existingFP != fp {
126				return nil, fmt.Errorf("record_id %q already exists with different content", id)
127			}
128			if _, ok := seenNew[fp]; ok {
129				duplicates = append(duplicates, id)
130				continue
131			}
132	
133			seenNew[fp] = struct{}{}
134			additions = append(additions, record)
135			existingByFingerprint[fp] = id
136			existingByID[id] = fp
137		}
138	
139		if len(additions) > 0 {
140			if err := appendRecords(ledgerPath, additions); err != nil {
141				return nil, err
142			}
143		}
144	
145		report := &AppendReport{
146			LedgerPath: ledgerPath,
147			Added:      len(additions),
148			Duplicates: append([]string(nil), duplicates...),
149		}
150		if len(duplicates) > 0 {
151			return report, &DuplicateRecordsError{RecordIDs: duplicates}
152		}
153		return report, nil
154	}
