156	// StableRecordID returns the deterministic content-derived record_id for a
157	// record that omits record_id.
158	func StableRecordID(doc map[string]any) (string, error) {
159		normalized, err := cloneDocument(doc)
160		if err != nil {
161			return "", err
162		}
163		delete(normalized, "record_id")
164		sum := sha256.Sum256(mustMarshal(normalized))
165		return hex.EncodeToString(sum[:]), nil
166	}
167	
168	func (v *Validator) normalizeRecord(doc map[string]any) (map[string]any, string, error) {
169		normalized, err := cloneDocument(doc)
170		if err != nil {
171			return nil, "", err
172		}
173		fp, err := fingerprintRecord(normalized)
174		if err != nil {
175			return nil, "", err
176		}
177		if id, _ := normalized["record_id"].(string); strings.TrimSpace(id) == "" {
178			normalized["record_id"] = fp
179		}
180		if err := v.schema.Validate(normalized); err != nil {
181			return nil, "", fmt.Errorf("schema validation failed: %w", err)
182		}
183		return normalized, fp, nil
184	}
185	
186	func fingerprintRecord(doc map[string]any) (string, error) {
187		normalized, err := cloneDocument(doc)
188		if err != nil {
189			return "", err
190		}
191		delete(normalized, "record_id")
192		sum := sha256.Sum256(mustMarshal(normalized))
193		return hex.EncodeToString(sum[:]), nil
194	}
195	
196	func loadLedgerRecords(path string) ([]map[string]any, error) {
197		info, err := os.Stat(path)
198		if err != nil {
199			if errors.Is(err, os.ErrNotExist) {
200				return nil, nil
201			}
202			return nil, fmt.Errorf("stat ledger %s: %w", path, err)
203		}
204		if info.Size() == 0 {
205			return nil, nil
206		}
207		return loadRecords(path)
208	}
209	
210	func loadRecords(path string) ([]map[string]any, error) {
211		raw, err := os.ReadFile(path)
212		if err != nil {
213			return nil, fmt.Errorf("read evidence file %s: %w", path, err)
214		}
215	
216		trimmed := bytes.TrimSpace(raw)
217		if len(trimmed) == 0 {
218			return nil, fmt.Errorf("evidence file %s is empty", path)
219		}
220	
221		if record, err := decodeObject(trimmed); err == nil {
222			return []map[string]any{record}, nil
223		}
224	
225		lines := bytes.Split(trimmed, []byte("\n"))
226		records := make([]map[string]any, 0, len(lines))
227		for i, line := range lines {
228			line = bytes.TrimSpace(line)
229			if len(line) == 0 {
230				continue
231			}
232			record, err := decodeObject(line)
233			if err != nil {
234				return nil, fmt.Errorf("%s line %d: %w", path, i+1, err)
235			}
236			records = append(records, record)
237		}
238		if len(records) == 0 {
239			return nil, fmt.Errorf("evidence file %s contains no records", path)
240		}
241		return records, nil
242	}
243	
244	func decodeObject(raw []byte) (map[string]any, error) {
245		var doc map[string]any
246		if err := json.Unmarshal(raw, &doc); err != nil {
247			return nil, err
248		}
249		return doc, nil
250	}
251	
252	func cloneDocument(doc map[string]any) (map[string]any, error) {
253		raw, err := json.Marshal(doc)
254		if err != nil {
255			return nil, fmt.Errorf("marshal evidence record: %w", err)
256		}
257		var out map[string]any
258		if err := json.Unmarshal(raw, &out); err != nil {
259			return nil, fmt.Errorf("clone evidence record: %w", err)
260		}

