 16	func TestEvidenceValidateCommand(t *testing.T) {
 17		repoRoot := benchRepoRoot(t)
 18		valid := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "valid-record.jsonl")
 19		invalid := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "invalid-record.jsonl")
 20	
 21		if code, out := runBenchCLI(t, repoRoot, "evidence", "validate", "--work-dir", repoRoot, valid); code != 0 {
 22			t.Fatalf("validate valid fixture exit=%d output=%s", code, out)
 23		}
 24	
 25		if code, out := runBenchCLI(t, repoRoot, "evidence", "validate", "--work-dir", repoRoot, invalid); code == 0 {
 26			t.Fatalf("validate invalid fixture unexpectedly succeeded: %s", out)
 27		} else if !strings.Contains(out, "artifact_sha256") && !strings.Contains(out, "evidence validate") {
 28			t.Fatalf("validate invalid fixture error missing useful context: %s", out)
 29		}
 30	}
