 32	func TestEvidenceAppendGeneratesStableRecordID(t *testing.T) {
 33		repoRoot := benchRepoRoot(t)
 34		input := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "append-input.jsonl")
 35		ledger := filepath.Join(t.TempDir(), "ledger.jsonl")
 36	
 37		if code, out := runBenchCLI(t, repoRoot, "evidence", "append", "--work-dir", repoRoot, "--in", input, "--ledger", ledger); code != 0 {
 38			t.Fatalf("append exit=%d output=%s", code, out)
 39		}
 40	
 41		record := readSingleJSONLRecord(t, ledger)
 42		doc := readSingleJSONRecord(t, input)
 43		wantID, err := evidence.StableRecordID(doc)
 44		if err != nil {
 45			t.Fatalf("StableRecordID: %v", err)
 46		}
 47		if got := mustStringField(t, record, "record_id"); got != wantID {
 48			t.Fatalf("ledger record_id = %q, want %q", got, wantID)
