 52	func TestEvidenceAppendDetectsDuplicates(t *testing.T) {
 53		repoRoot := benchRepoRoot(t)
 54		input := filepath.Join(repoRoot, "cmd", "bench", "testdata", "benchmark-evidence", "append-input.jsonl")
 55		ledger := filepath.Join(t.TempDir(), "ledger.jsonl")
 56	
 57		validator, err := evidence.NewValidator(repoRoot)
 58		if err != nil {
 59			t.Fatalf("NewValidator: %v", err)
 60		}
 61	
 62		report, err := validator.AppendLedger(input, ledger)
 63		if err != nil {
 64			t.Fatalf("first append: %v", err)
 65		}
 66		if report.Added != 1 {
 67			t.Fatalf("first append added %d records, want 1", report.Added)
 68		}
 69	
 70		report, err = validator.AppendLedger(input, ledger)
 71		var dupErr *evidence.DuplicateRecordsError
 72		if !errors.As(err, &dupErr) {
 73			t.Fatalf("second append error = %v, want DuplicateRecordsError", err)
 74		}
 75		if report == nil || len(report.Duplicates) == 0 {
 76			t.Fatalf("second append did not report duplicates: %#v", report)
 77		}
 78	
 79		raw, err := os.ReadFile(ledger)
 80		if err != nil {
 81			t.Fatalf("read ledger: %v", err)
 82		}
 83		if got := len(bytes.Split(bytes.TrimSpace(raw), []byte("\n"))); got != 1 {
 84			t.Fatalf("ledger line count = %d, want 1", got)
 85		}
 86	}
