 88	func runBenchCLI(t *testing.T, repoRoot string, args ...string) (int, string) {
 89		t.Helper()
 90	
 91		cmd := exec.Command("go", append([]string{"run", "."}, args...)...)
 92		cmd.Dir = filepath.Join(repoRoot, "cmd", "bench")
 93		cmd.Env = append(os.Environ(), "GOWORK=off")
 94		out, err := cmd.CombinedOutput()
 95		if err == nil {
 96			return 0, string(out)
 97		}
 98		if exitErr, ok := err.(*exec.ExitError); ok {
 99			return exitErr.ExitCode(), string(out)
100		}
101		t.Fatalf("go run failed: %v\n%s", err, string(out))
102		return 1, string(out)
103	}
