139	func mustStringField(t *testing.T, doc map[string]any, key string) string {
140		t.Helper()
141	
142		got, ok := doc[key]
143		if !ok {
144			t.Fatalf("missing %s", key)
145		}
146		str, ok := got.(string)
147		if !ok {
